mapper.sql:
where e.plant_cd = #{plantCd}
  and c.occurred_at >= #{from} and c.occurred_at < #{to}
  and c.equip_id = #{equipId}
  and c.metric_cd = #{metricCd}

mapper.select:
order by
c.recorded_at desc e.equip_cd desc c.metric_cd desc c.occurred_at desc ,
c.count_id desc limit #{page.size} offset #{page.offset}
